import { createContext } from 'octane';
import { STRINGS } from './strings.ts';

// The contexts the app's components read. The assistant message's catalog
// reads several of them per component, as a design-system-built catalog does.
export const LocaleContext = /* @__PURE__ */ createContext({ locale: 'en-US', strings: STRINGS });
export const ThemeContext = /* @__PURE__ */ createContext({ theme: 'light', accent: 'teal', density: 'comfortable' });
export const GatesContext = /* @__PURE__ */ createContext(null as any);
export const TelemetryContext = /* @__PURE__ */ createContext(null as any);
export const LayoutContext = /* @__PURE__ */ createContext({ sidebarOpen: true, width: 1440, compact: false });
export const SessionContext = /* @__PURE__ */ createContext({ signedIn: false, persona: 'anonymous', region: 'US' });
export const MessageContext = /* @__PURE__ */ createContext({ id: '', role: 'assistant', status: 'done', turn: 0 });
export const StreamingContext = /* @__PURE__ */ createContext({ streaming: false, revision: 0, seenWords: 0 });
export const WidgetContext = /* @__PURE__ */ createContext(null as any);
export const ActionsContext = /* @__PURE__ */ createContext(null as any);

